{"command": "cd sessions && python3 -c "
import json, glob, os, datetime
def ts(v):
    if isinstance(v,(int,float)):
        if v > 1e12: v = v/1000
        return datetime.datetime.fromtimestamp(v).strftime('%m-%d %H:%M')
    return str(v)[:16]
files = sorted(glob.glob('*.json'), key=lambda x: -os.path.getmtime(x))
for f in files:
    d = json.load(open(f))
    t = str(d.get('title') or '(无标题)')
    t = t.replace(chr(10),' ')[:40]
    s = str(d.get('summary') or '')[:50].replace(chr(10),' ')
    print(f\"{ts(d.get('updated_at'))} | {t} | {d.get('message_count')}msg | {f[:-5]}\")
    if s: print(f\"    summary: {s}\")
""}
